function div(a,b){return ~~(a/b);}
function mod(a,b){return a-~~(a/b)*b;}
function jalCal(jy){var bk=[-61,9,38,199,426,686,756,818,1111,1181,1210,1635,2060,2097,2192,2262,2324,2394,2456,3178],bl=bk.length,gy=jy+621,leapJ=-14,jp=bk[0],jm,jump=0,leap,n,i;if(jy<jp||jy>=bk[bl-1])throw new Error('سال شمسی نامعتبر');for(i=1;i<bl;i++){jm=bk[i];jump=jm-jp;if(jy<jm)break;leapJ=leapJ+div(jump,33)*8+div(mod(jump,33),4);jp=jm;}n=jy-jp;leapJ=leapJ+div(n,33)*8+div(mod(n,33)+3,4);if(mod(jump,33)===4&&jump-n===4)leapJ+=1;var leapG=div(gy,4)-div((div(gy,100)+1)*3,4)-150,march=20+leapJ-leapG;if(jump-n<6)n=n-jump+div(jump+4,33)*33;leap=mod(mod(n+1,33)-1,4);if(leap===-1)leap=4;return{leap:leap,gy:gy,march:march};}
function g2d(gy,gm,gd){var d=div((gy+div(gm-8,6)+100100)*1461,4)+div(153*mod(gm+9,12)+2,5)+gd-34840408;d=d-div(div(gy+100100+div(gm-8,6),100)*3,4)+752;return d;}
function d2g(jdn){var j=4*jdn+139361631;j=j+div(div(4*jdn+183187720,146097)*3,4)*4-3908;var i=div(mod(j,1461),4)*5+308,gd=div(mod(i,153),5)+1,gm=mod(div(i,153),12)+1,gy=div(j,1461)-100100+div(8-gm,6);return{gy:gy,gm:gm,gd:gd};}
function d2j(jdn){var gy=d2g(jdn).gy,jy=gy-621,r=jalCal(jy),jdn1f=g2d(gy,3,r.march),k=jdn-jdn1f,jm,jd;if(k>=0){if(k<=185){jm=1+div(k,31);jd=mod(k,31)+1;return{jy:jy,jm:jm,jd:jd};}k-=186;}else{jy-=1;k+=179;if(r.leap===1)k+=1;}jm=7+div(k,30);jd=mod(k,30)+1;return{jy:jy,jm:jm,jd:jd};}
function j2d(jy,jm,jd){var r=jalCal(jy);return g2d(r.gy,3,r.march)+(jm-1)*31-div(jm,7)*(jm-7)+jd-1;}
function pad(n){return String(n).length<2?'0'+n:String(n);}
function toJfromISO(iso){var p=String(iso).slice(0,10).split('-');return d2j(g2d(+p[0],+p[1],+p[2]));}
function jToISO(jy,jm,jd){var g=d2g(j2d(jy,jm,jd));return g.gy+'-'+pad(g.gm)+'-'+pad(g.gd);}
function fa2en(s){return String(s==null?'':s).replace(/[۰-۹]/g,function(d){return '۰۱۲۳۴۵۶۷۸۹'.indexOf(d);}).replace(/[٠-٩]/g,function(d){return '٠١٢٣٤٥٦٧٨٩'.indexOf(d);});}
function toNum(v){var s=fa2en(v).replace(/[^0-9.\-]/g,'');var n=Number(s);return Number.isFinite(n)?n:0;}

function parseDate(v, todayISO) {
  if (v === null || v === undefined || v === '') return { iso: todayISO, guessed: true };
  if (v instanceof Date && !isNaN(v.getTime())) {
    return { iso: v.toISOString().slice(0, 10), guessed: false };
  }
  const raw = fa2en(v).trim();
  const serial = Number(raw);
  if (raw !== '' && Number.isFinite(serial) && serial > 20000 && serial < 80000 && raw.indexOf('/') < 0 && raw.indexOf('-') < 0) {
    const ms = Math.round((serial - 25569) * 86400000);
    return { iso: new Date(ms).toISOString().slice(0, 10), guessed: false };
  }
  const parts = raw.split(/[\/\-\.]/).map(function (x) { return parseInt(x, 10); });
  if (parts.length >= 3 && parts.every(function (n) { return Number.isFinite(n); })) {
    if (parts[0] > 1600) return { iso: parts[0] + '-' + pad(parts[1]) + '-' + pad(parts[2]), guessed: false };
    if (parts[0] > 1200 && parts[0] < 1600) return { iso: jToISO(parts[0], parts[1], parts[2]), guessed: false };
  }
  const d = new Date(raw);
  if (!isNaN(d.getTime())) return { iso: d.toISOString().slice(0, 10), guessed: false };
  return { iso: todayISO, guessed: true };
}

const SYN = {
  date: ['تاریخ', 'تاريخ', 'تاریخ_شمسی', 'تاریخ شمسی', 'تاریخ میلادی', 'روز', 'date', 'Date'],
  amount: ['مبلغ', 'مبلغ (تومان)', 'مبلغ تومان', 'قیمت', 'بها', 'جمع', 'جمع کل', 'amount', 'Amount', 'price', 'total', 'مبلغ_تومان', 'ارزش'],
  desc: ['شرح', 'شرح هزینه', 'توضیح', 'توضیحات', 'بابت', 'عنوان', 'description', 'Description', 'شرح_آورده'],
  category: ['دسته', 'دسته هزینه', 'دسته_هزینه', 'گروه', 'category', 'Category', 'نوع هزینه'],
  payer: ['پرداخت کننده', 'پرداخت_کننده', 'نام شاگرد', 'شاگرد', 'نام', 'مشتری', 'payer', 'name', 'دانش آموز'],
  klass: ['کلاس', 'نام کلاس', 'نام_کلاس', 'کد کلاس', 'کد_کلاس', 'class', 'دوره'],
  teacher: ['مدرس', 'نام مدرس', 'نام_مدرس', 'کد مدرس', 'کد_مدرس', 'استاد', 'teacher'],
  ktype: ['نوع کلاس', 'نوع_کلاس', 'نوع', 'type', 'حضوری/آنلاین'],
  sessions: ['تعداد جلسه', 'تعداد_جلسه', 'جلسه', 'تعداد جلسات', 'sessions'],
  students: ['تعداد شاگرد', 'تعداد_شاگرد', 'شاگرد', 'نفرات', 'تعداد نفرات', 'students'],
  percent: ['درصد', 'درصد مدرس', 'درصد_مدرس', 'سهم', 'percent'],
  paymethod: ['روش پرداخت', 'روش_پرداخت', 'نحوه پرداخت', 'payment'],
  investor: ['سرمایه گذار', 'سرمایه‌گذار', 'نام سرمایه گذار', 'نام_سرمایه_گذار', 'کد سرمایه گذار', 'کد_سرمایه_گذار', 'investor'],
  ctype: ['نوع آورده', 'نوع_آورده'],
  incomeType: ['نوع درآمد', 'نوع_درآمد', 'منبع'],
  ref: ['شماره پیگیری', 'شماره_پیگیری', 'کد رهگیری', 'reference'],
  counterparty: ['طرف حساب', 'طرف_حساب', 'فروشنده', 'موجر', 'تامین کننده'],
};

function pick(row, key) {
  const names = SYN[key] || [];
  const keys = Object.keys(row);
  for (let i = 0; i < names.length; i++) {
    for (let k = 0; k < keys.length; k++) {
      if (String(keys[k]).trim() === names[i]) return row[keys[k]];
    }
  }
  for (let i = 0; i < names.length; i++) {
    for (let k = 0; k < keys.length; k++) {
      const kk = String(keys[k]).trim();
      if (kk.indexOf(names[i]) >= 0 || names[i].indexOf(kk) >= 0) return row[keys[k]];
    }
  }
  return undefined;
}

function safeRows(name) { try { return $(name).all().map(function (i) { return i.json || {}; }); } catch (e) { return []; } }

let raw = [];
let source = '';
let declaredType = '';
try {
  raw = $('استخراج از فایل فرم').all().map(function (i) { return i.json || {}; });
  source = 'اکسل-فرم';
  declaredType = String($('آپلود فایل اکسل').first().json['نوع_داده'] || '');
} catch (e) { raw = []; }

if (!raw.length) {
  try {
    raw = $('استخراج از پیوست ایمیل').all().map(function (i) { return i.json || {}; });
    source = 'اکسل-ایمیل';
    const subj = String($('ایمیل با پیوست اکسل').first().json.subject || '');
    if (subj.indexOf('درآمد') >= 0) declaredType = 'درآمد';
    else if (subj.indexOf('هزینه') >= 0) declaredType = 'هزینه';
    else if (subj.indexOf('تدریس') >= 0 || subj.indexOf('جلسه') >= 0) declaredType = 'جلسات تدریس';
    else if (subj.indexOf('سرمایه') >= 0 || subj.indexOf('آورده') >= 0) declaredType = 'آورده سرمایه';
  } catch (e) { raw = []; }
}

raw = raw.filter(function (r) {
  const vals = Object.keys(r).map(function (k) { return r[k]; });
  return vals.some(function (v) { return v !== '' && v !== null && v !== undefined; });
});

if (!declaredType && raw.length) {
  const probe = raw[0];
  if (pick(probe, 'category') !== undefined) declaredType = 'هزینه';
  else if (pick(probe, 'sessions') !== undefined || pick(probe, 'klass') !== undefined) declaredType = 'جلسات تدریس';
  else if (pick(probe, 'investor') !== undefined) declaredType = 'آورده سرمایه';
  else declaredType = 'درآمد';
}

const settings = {};
safeRows('تنظیمات').forEach(function (r) { if (r['کلید']) settings[String(r['کلید']).trim()] = r['مقدار']; });
const teachers = safeRows('مدرسین').filter(function (r) { return r['کد_مدرس']; });
const classes = safeRows('کلاس‌ها').filter(function (r) { return r['کد_کلاس']; });
const investors = safeRows('سرمایه‌گذاران').filter(function (r) { return r['کد_سرمایه_گذار']; });

const todayISO = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Tehran' });
const now = new Date().toISOString();
const stamp = Date.now().toString(36).slice(-4).toUpperCase();

function findClass(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return {};
  const code = s.indexOf(' — ') > 0 ? s.split(' — ')[0] : s;
  let hit = classes.filter(function (c) { return String(c['کد_کلاس']).trim() === code; })[0];
  if (!hit) hit = classes.filter(function (c) { return String(c['نام_کلاس']).trim() === s; })[0];
  if (!hit) hit = classes.filter(function (c) { return s.indexOf(String(c['نام_کلاس']).trim()) >= 0; })[0];
  return hit || {};
}
function findTeacher(v, fallbackCode) {
  const s = String(v == null ? '' : v).trim();
  let hit = null;
  if (s) {
    hit = teachers.filter(function (t) { return String(t['کد_مدرس']).trim() === s || String(t['نام_مدرس']).trim() === s; })[0];
  }
  if (!hit && fallbackCode) {
    hit = teachers.filter(function (t) { return String(t['کد_مدرس']).trim() === String(fallbackCode).trim(); })[0];
  }
  return hit || {};
}
function findInvestor(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return {};
  const code = s.indexOf(' — ') > 0 ? s.split(' — ')[0] : s;
  let hit = investors.filter(function (i) { return String(i['کد_سرمایه_گذار']).trim() === code; })[0];
  if (!hit) hit = investors.filter(function (i) { return String(i['نام_سرمایه_گذار']).trim() === s; })[0];
  return hit || {};
}

const out = [];
let ok = 0;
let bad = 0;
const problems = [];

raw.forEach(function (r, index) {
  const rowNo = index + 2;
  const dt = parseDate(pick(r, 'date'), todayISO);
  const j = toJfromISO(dt.iso);
  const shamsi = j.jy + '/' + pad(j.jm) + '/' + pad(j.jd);
  const amount = toNum(pick(r, 'amount'));
  const note = (dt.guessed ? 'تاریخ خوانده نشد — امروز ثبت شد. ' : '') + String(pick(r, 'desc') || '');

  if (declaredType === 'هزینه') {
    if (amount <= 0) { bad++; problems.push('ردیف ' + rowNo + ': مبلغ نامعتبر'); return; }
    out.push({ json: {
      _target: 'هزینه',
      'شناسه': 'EX-' + j.jy + pad(j.jm) + '-X' + stamp + rowNo,
      'تاریخ_شمسی': shamsi, 'تاریخ_میلادی': dt.iso, 'سال_شمسی': j.jy, 'ماه_شمسی': j.jm,
      'دسته_هزینه': String(pick(r, 'category') || 'سایر'),
      'شرح': String(pick(r, 'desc') || 'واردات اکسل'),
      'مبلغ': amount,
      'روش_پرداخت': String(pick(r, 'paymethod') || ''),
      'طرف_حساب': String(pick(r, 'counterparty') || ''),
      'نوع_هزینه': 'متغیر',
      'توضیح': note,
      'منبع': source,
      'زمان_ثبت': now,
    } });
    ok++;
    return;
  }

  if (declaredType === 'درآمد') {
    if (amount <= 0) { bad++; problems.push('ردیف ' + rowNo + ': مبلغ نامعتبر'); return; }
    const cls = findClass(pick(r, 'klass'));
    out.push({ json: {
      _target: 'درآمد',
      'شناسه': 'IN-' + j.jy + pad(j.jm) + '-X' + stamp + rowNo,
      'تاریخ_شمسی': shamsi, 'تاریخ_میلادی': dt.iso, 'سال_شمسی': j.jy, 'ماه_شمسی': j.jm,
      'نوع_درآمد': String(pick(r, 'incomeType') || 'شهریه شاگرد'),
      'پرداخت_کننده': String(pick(r, 'payer') || ''),
      'کد_کلاس': cls['کد_کلاس'] || '',
      'نام_کلاس': cls['نام_کلاس'] || '',
      'کد_مدرس': cls['کد_مدرس'] || '',
      'مبلغ': amount,
      'روش_پرداخت': String(pick(r, 'paymethod') || ''),
      'شماره_پیگیری': String(pick(r, 'ref') || ''),
      'توضیح': note,
      'منبع': source,
      'زمان_ثبت': now,
    } });
    ok++;
    return;
  }

  if (declaredType === 'جلسات تدریس') {
    const cls = findClass(pick(r, 'klass'));
    const teacher = findTeacher(pick(r, 'teacher'), cls['کد_مدرس']);
    if (!cls['کد_کلاس'] && !teacher['کد_مدرس']) { bad++; problems.push('ردیف ' + rowNo + ': کلاس و مدرس شناسایی نشد'); return; }
    const type = String(pick(r, 'ktype') || cls['نوع_کلاس'] || 'حضوری');
    const isOnline = type.indexOf('آنلاین') >= 0;
    const sessions = toNum(pick(r, 'sessions')) || 1;
    const students = toNum(pick(r, 'students'));
    let gross = amount;
    if (!gross) {
      const tuition = toNum(cls['شهریه_هر_نفر']);
      const total = toNum(cls['تعداد_جلسات_دوره']);
      gross = Math.round((total > 0 ? tuition / total : tuition) * students * sessions);
    }
    let pct = toNum(pick(r, 'percent'));
    if (!pct) pct = toNum(cls['درصد_مدرس_اختصاصی']);
    if (!pct) pct = isOnline ? toNum(teacher['درصد_آنلاین']) : toNum(teacher['درصد_حضوری']);
    if (!pct) pct = isOnline ? (toNum(settings['درصد_پیشفرض_آنلاین']) || 60) : (toNum(settings['درصد_پیشفرض_حضوری']) || 70);
    out.push({ json: {
      _target: 'جلسات',
      'شناسه': 'TS-' + j.jy + pad(j.jm) + '-X' + stamp + rowNo,
      'تاریخ_شمسی': shamsi, 'تاریخ_میلادی': dt.iso, 'سال_شمسی': j.jy, 'ماه_شمسی': j.jm,
      'کد_مدرس': teacher['کد_مدرس'] || cls['کد_مدرس'] || '',
      'نام_مدرس': teacher['نام_مدرس'] || '',
      'کد_کلاس': cls['کد_کلاس'] || '',
      'نام_کلاس': cls['نام_کلاس'] || '',
      'نوع_کلاس': type,
      'تعداد_جلسه': sessions,
      'تعداد_شاگرد': students,
      'درآمد_ناخالص': gross,
      'درصد_مدرس': pct,
      'سهم_مدرس': Math.round(gross * pct / 100),
      'وضعیت_تسویه': 'تسویه نشده',
      'توضیح': note,
      'منبع': source,
      'زمان_ثبت': now,
    } });
    ok++;
    return;
  }

  if (amount <= 0) { bad++; problems.push('ردیف ' + rowNo + ': مبلغ نامعتبر'); return; }
  const inv = findInvestor(pick(r, 'investor'));
  out.push({ json: {
    _target: 'سرمایه',
    'شناسه': 'CP-' + j.jy + pad(j.jm) + '-X' + stamp + rowNo,
    'تاریخ_شمسی': shamsi, 'تاریخ_میلادی': dt.iso, 'سال_شمسی': j.jy, 'ماه_شمسی': j.jm,
    'کد_سرمایه_گذار': inv['کد_سرمایه_گذار'] || '',
    'نام_سرمایه_گذار': inv['نام_سرمایه_گذار'] || String(pick(r, 'investor') || ''),
    'نوع_آورده': String(pick(r, 'ctype') || 'نقدی'),
    'شرح_آورده': String(pick(r, 'desc') || ''),
    'مبلغ_تومان': amount,
    'نرخ_طلای18_روز': '',
    'نرخ_دلار_روز': '',
    'معادل_گرم_طلا': '',
    'معادل_دلار': '',
    'دسته': 'سرمایه اولیه (سال‌های قبل)',
    'توضیح': note + ' [واردات اکسل — نرخ روز ثبت نشد، تعدیل با تورم رسمی]',
    'منبع': source,
    'زمان_ثبت': now,
  } });
  ok++;
});

if (!out.length) {
  out.push({ json: {
    _target: 'خطا',
    'زمان': now,
    'منبع': source || 'اکسل',
    'نوع_رکورد': declaredType || 'نامشخص',
    'شناسه_مرتبط': '',
    'وضعیت': 'ناموفق',
    'پیام': 'هیچ ردیف معتبری پیدا نشد. ' + problems.slice(0, 5).join(' | '),
    'داده_خام': JSON.stringify(raw.slice(0, 3)),
  } });
}

out.forEach(function (o) {
  o.json._meta = { ok: ok, bad: bad, total: raw.length, type: declaredType, source: source, problems: problems.slice(0, 15) };
});

return out;

const SHEET_URL = 'https://docs.google.com/spreadsheets/d/12j12zy8lqxlft1mBIZ0THmG-Ro24TZmUqijVwMpuTg4/edit';
const meta = ($('نرمال‌سازی ردیف‌های اکسل').first().json._meta) || { ok: 0, bad: 0, total: 0, type: '', source: '', problems: [] };

const problemsHtml = (meta.problems || []).length
  ? '<ul>' + meta.problems.map(function (p) { return '<li>' + p + '</li>'; }).join('') + '</ul>'
  : '<div style="color:#137333">همه ردیف‌ها سالم بودند.</div>';

const html = '<div dir="rtl" style="font-family:Tahoma,Arial,sans-serif;font-size:14px;max-width:640px">'
  + '<h2 style="margin:0 0 10px">نتیجه واردات فایل اکسل</h2>'
  + '<table border="1" cellpadding="7" style="border-collapse:collapse;border-color:#dadce0;width:100%">'
  + '<tr><td>نوع داده</td><td><b>' + meta.type + '</b></td></tr>'
  + '<tr><td>منبع</td><td>' + meta.source + '</td></tr>'
  + '<tr><td>ردیف‌های فایل</td><td>' + meta.total + '</td></tr>'
  + '<tr><td>ثبت‌شده</td><td style="color:#137333"><b>' + meta.ok + '</b></td></tr>'
  + '<tr><td>رد شده</td><td style="color:#c5221f"><b>' + meta.bad + '</b></td></tr>'
  + '</table>'
  + '<h3 style="margin:16px 0 6px">ردیف‌های مشکل‌دار</h3>' + problemsHtml
  + '<p><a href="' + SHEET_URL + '" style="background:#1a73e8;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block">باز کردن دفتر حسابداری</a></p>'
  + '</div>';

const text = 'واردات ' + meta.type + ': ' + meta.ok + ' ردیف ثبت شد، ' + meta.bad + ' ردیف رد شد (از ' + meta.total + ' ردیف).';

return [{ json: { ok: meta.ok, bad: meta.bad, total: meta.total, type: meta.type, html: html, پیام: text } }];
